using System.Text.Json;
namespace ONEXTweaks.WidgetBridge;
internal static class ControllerTargetVerification
{
 private sealed class Capture:IControllerCaptureRuntime{
  internal int Starts,Stops;internal bool Wait,Fail;internal ControllerPolicy Current=new();private ControllerRuntimeState state=new(false,false,0,-1,null,[],0);
  public ControllerRuntimeState Read()=>state;public void Policy(ControllerPolicy value){Current=value;}
  public Task Start(){Starts++;if(Wait)throw new ControllerInputNotNeutralException("Release input");if(Fail)throw new IOException("Owned model failure");state=new(true,false,0,Current.OutputTarget=="Xbox360"?1:-1,null,[],1,OutputTarget:Current.OutputTarget);return Task.CompletedTask;}
  public Task Stop(){Stops++;state=state with{Running=false,Error=null,VirtualSlot=-1};return Task.CompletedTask;}public ValueTask DisposeAsync()=>ValueTask.CompletedTask;
 }
 internal static async Task<int> Models(string file){
  int checks=0;void Check(bool ok,string why){checks++;if(!ok)throw new IOException(why);}string folder=Path.Combine(Path.GetTempPath(),"ONEXTweaks-TargetModel-"+Guid.NewGuid().ToString("N")),reports=Path.Combine(folder,"Reports");Directory.CreateDirectory(reports);
  try{
   var legacy=JsonSerializer.Deserialize<ControllerPolicy>("{}",Backend.Program.Json)!.Validate();Check(legacy.OutputTarget=="Xbox360"&&!JsonSerializer.Serialize(legacy,Backend.Program.Json).Contains("virtualTarget"),"Legacy target changed or was eagerly persisted");
   var ds4=new ControllerPolicy(VirtualTarget:"DualShock4").Validate();Check(JsonSerializer.Deserialize<ControllerPolicy>(JsonSerializer.Serialize(ds4,Backend.Program.Json),Backend.Program.Json)!.OutputTarget=="DualShock4","DS4 target did not roundtrip");Check((ds4 with{KeyboardMouse=new()}).Validate().OutputTarget=="Xbox360"&&(ds4 with{KeyboardMouse=new()}).VirtualTarget=="DualShock4","Keyboard/mouse must temporarily use Xbox without losing saved DS4 choice");
   foreach(string invalid in new[]{"","ds4","DS4","DualSenseEdge","SwitchPro","Unknown"}){bool rejected=false;try{new ControllerPolicy(VirtualTarget:invalid).Validate();}catch(InvalidDataException){rejected=true;}Check(rejected,"An unverified target was accepted");}
   var source=new ControllerOutput(new(0xc123,51,72,100,-200,300,-400),System.Collections.Immutable.ImmutableHashSet.Create(17),System.Collections.Immutable.ImmutableHashSet.Create("left"),3,7,9,["X"]);var relay=new ControllerDs4NavigationRelay();
   Check(ReferenceEquals(relay.Apply(source,false,0),source)&&!relay.NeedsTick,"Closed Game Bar changed gameplay output");Check(!relay.Apply(source,true,10).Keys.Contains(93),"Held gameplay X became a phantom context press on overlay entry");relay.Apply(source with{Pad=source.Pad with{Buttons=0}},true,20);var first=relay.Apply(source,true,30);Check(first.Keys.SetEquals([17,93])&&first.Pad==source.Pad with{Buttons=(ushort)(source.Pad.Buttons&~0x4000)}&&first.Mouse==source.Mouse&&first.Wheel==source.Wheel,"Overlay relay changed unrelated outputs");Check(relay.NeedsTick,"Context key release did not schedule a tick");Check(relay.Apply(source,true,109).Keys.Contains(93),"Context pulse ended too early");Check(!relay.Apply(source,true,110).Keys.Contains(93)&&!relay.NeedsTick,"Context pulse was held/repeated");Check(!relay.Apply(source,true,5000).Keys.Contains(93),"Long X hold retriggered context");relay.Apply(source with{Pad=new()},true,5010);Check(relay.Apply(source,true,5020).Keys.Contains(93),"Second X press did not rearm");Check(!relay.Apply(source with{Pad=new()},true,5030).Keys.Contains(93),"Early release left context held");Check(ReferenceEquals(relay.Apply(source,false,5040),source)&&!relay.NeedsTick,"Leaving overlay did not preserve normal game input");
   var fake=new Capture();string stamp="desktop:1";ControllerProfileStore Read()=>JsonSerializer.Deserialize<ControllerProfileStore>(File.ReadAllText(Path.Combine(folder,"controller-profiles.json")),Backend.Program.Json)!;
   await using(var profiles=new ControllerProfiles(reports,()=>stamp,()=>"global",()=>[("global","Global"),("game","Owned linked game")],capture:fake)){
    async Task Change(object value){using var json=JsonDocument.Parse(JsonSerializer.Serialize(value,Backend.Program.Json));await profiles.Mutate(json.RootElement);}
    await Change(new{operation="enable",enabled=true});Check(fake.Starts==1&&fake.Current.OutputTarget=="Xbox360","Default virtual profile failed");await Change(new{operation="edit",id="global",policy=ds4});Check(fake.Stops==1&&fake.Starts==2&&fake.Read().OutputTarget=="DualShock4"&&Read().Enabled,"Target change did not stop old output before starting DS4");await profiles.MaintainRuntime();Check(fake.Stops==1&&fake.Starts==2,"Stable target was unnecessarily reconnected");
    await Change(new{operation="create",name="Owned target model"});string manual=profiles.EditingId;await Change(new{operation="edit",id=manual,policy=legacy});Check(fake.Current.OutputTarget=="Xbox360"&&fake.Stops==2,"Manual target did not switch");await Change(new{operation="select",id="global"});Check(fake.Current.OutputTarget=="DualShock4","Profile selection lost DS4 choice");int starts=fake.Starts,stops=fake.Stops;await Change(new{operation="create",performanceProfileId="game"});string linked=profiles.EditingId;await Change(new{operation="edit",id=linked,policy=legacy});Check(fake.Starts==starts&&fake.Stops==stops,"Inactive linked profile edit reconnected active controller");await Change(new{operation="select",id="global"});
    fake.Wait=true;await Change(new{operation="edit",id="global",policy=legacy});Check(!fake.Read().Running&&Read().Enabled,"Held input did not defer target capture while preserving desired Virtual preference");fake.Wait=false;await profiles.MaintainRuntime(true);Check(fake.Read().Running&&fake.Read().OutputTarget=="Xbox360","Release did not resume selected target");
    fake.Fail=true;bool failed=false;try{await Change(new{operation="edit",id="global",policy=ds4});}catch(IOException){failed=true;}Check(failed&&!Read().Enabled&&!fake.Read().Running,"Target start failure did not return to protected Hardware mode");Check(Read().Global.Policy.VirtualTarget=="DualShock4","Failed runtime transition lost saved target");
   }
   var reload=new Capture();await using(var profiles=new ControllerProfiles(reports,()=>stamp,()=>"global",()=>[("global","Global")],capture:reload)){await profiles.Resume();Check(reload.Starts==0&&Read().Global.Policy.OutputTarget=="DualShock4","Reload forgot target or enabled failed capture");}
   await File.WriteAllTextAsync(file,JsonSerializer.Serialize(new{passed=true,checks,modelOnly=true,ownerPreferenceWrites=0,physicalOwnerInputTested=false},Backend.Program.Json));return 0;
  }catch(Exception e){await File.WriteAllTextAsync(file,JsonSerializer.Serialize(new{passed=false,checks,error=e.Message},Backend.Program.Json));return 2;}
  finally{Directory.Delete(folder,true);}
 }
 internal static async Task<int> Native(string file){
  int checks=0,transitions=0;void Check(bool ok,string why){checks++;if(!ok)throw new IOException(why);}string reports=Path.GetDirectoryName(file)!,owner=Path.Combine(reports,"..","controller-profiles.json");byte[] originalOwner=await File.ReadAllBytesAsync(owner);ControllerHideState before;using(var hide=new ControllerHidHide())before=hide.Read();
  string folder=Path.Combine(Path.GetTempPath(),"ONEXTweaks-TargetNative-"+Guid.NewGuid().ToString("N")),ownReports=Path.Combine(folder,"Reports");Directory.CreateDirectory(ownReports);ControllerRemapper? runtime=null;string? error=null;
  try{
   using(var ownerJson=JsonDocument.Parse(originalOwner))Check(!ownerJson.RootElement.GetProperty("enabled").GetBoolean(),"Protect owner's desired active Virtual preference");Check(!File.Exists(ControllerCaptureLease.LeaseFile(reports))&&ControllerNative.Slots().SequenceEqual(new[]{0})&&ControllerNative.Read(0,out var source)&&ControllerNative.Neutral(source),"Protect owner active input/capture");runtime=new ControllerRemapper(reports);
   await using(var profiles=new ControllerProfiles(ownReports,()=>"desktop:1",()=>"global",()=>[("global","Global")],capture:runtime)){
    async Task Change(object value){using var json=JsonDocument.Parse(JsonSerializer.Serialize(value,Backend.Program.Json));await profiles.Mutate(json.RootElement);}
    async Task Assert(string target){var state=runtime.Read();Check(state.Running&&state.OutputTarget==target,"Actual running output does not match selected target");int[] visible=await ControllerRemapper.Observe(reports);Check(visible.Length==(target=="Xbox360"?1:0),"Actual independent visibility is inconsistent with target");Check(File.Exists(ControllerCaptureLease.LeaseFile(reports))&&ControllerNative.Read(0,out _),"Physical source/lease lost during target transition");}
    await Change(new{operation="enable",enabled=true});await Assert("Xbox360");
    foreach(string target in new[]{"DualShock4","Xbox360","DualShock4"}){Check(ControllerNative.Read(0,out var neutral)&&ControllerNative.Neutral(neutral),"Owner began using physical controller; neutral target verification stopped");await Change(new{operation="edit",id="global",policy=new ControllerPolicy(VirtualTarget:target)});await Assert(target);transitions++;await profiles.MaintainRuntime(true);Check(runtime.Read().Running&&runtime.Read().OutputTarget==target,"Unchanged selected type lost its live output");}
    await Change(new{operation="enable",enabled=false});Check(!runtime.Read().Running&&!File.Exists(ControllerCaptureLease.LeaseFile(reports))&&(await ControllerRemapper.Observe(reports)).SequenceEqual(new[]{0}),"Hardware stop after DS4 selection did not restore physical input");
   }
   runtime=null;var saved=JsonSerializer.Deserialize<ControllerProfileStore>(await File.ReadAllTextAsync(Path.Combine(folder,"controller-profiles.json")),Backend.Program.Json)!;Check(saved.Global.Policy.OutputTarget=="DualShock4"&&!saved.Enabled,"Actual persisted target lost on stop");
   await using(var reload=new ControllerProfiles(ownReports,()=>"desktop:1",()=>"global",()=>[("global","Global")],capture:new ControllerRemapper(reports))){await reload.Resume();using var data=JsonDocument.Parse(JsonSerializer.Serialize(reload.Read(),Backend.Program.Json));Check(data.RootElement.GetProperty("editor").GetProperty("policy").GetProperty("virtualTarget").GetString()=="DualShock4"&&!data.RootElement.GetProperty("runtime").GetProperty("running").GetBoolean(),"Restart lost selected type or enabled an unwanted capture");}
  }catch(Exception e){error=e.Message.Replace(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"<user>",StringComparison.OrdinalIgnoreCase);}
  finally{
   if(runtime!=null)try{await runtime.DisposeAsync();}catch(Exception e){error=(error??"")+"; "+e.Message;}try{await ControllerCaptureLease.RecoverStopped(reports);}catch(Exception e){error=(error??"")+"; "+e.Message;}ControllerHideState after;using(var hide=new ControllerHidHide())after=hide.Read();bool hideRestored=before.Active==after.Active&&before.Inverse==after.Inverse&&before.Devices.SequenceEqual(after.Devices)&&before.Applications.SequenceEqual(after.Applications),ownerPreserved=false;byte[] currentOwner=await File.ReadAllBytesAsync(owner);ownerPreserved=originalOwner.SequenceEqual(currentOwner);
   await File.WriteAllTextAsync(file,JsonSerializer.Serialize(new{passed=error==null&&hideRestored&&ownerPreserved,checks,error,hidHideRestored=hideRestored,ownerControllerPreferencesPreserved=ownerPreserved,actualProfileTargetTransitions=transitions,actualViiperAndIndependentObserver=transitions>0,ownTemporaryProfileStore=true,ownerPhysicalInputTested=false},Backend.Program.Json));Directory.Delete(folder,true);
  }
  using var result=JsonDocument.Parse(await File.ReadAllTextAsync(file));return result.RootElement.GetProperty("passed").GetBoolean()?0:2;
 }
}
